(function(){const loadedScripts={};window.loadScript=function(url){if(loadedScripts[url]){return loadedScripts[url]}
loadedScripts[url]=new Promise(function(resolve,reject){const script=document.createElement('script');script.src=url;script.async=!0;script.onload=resolve;script.onerror=function(){delete loadedScripts[url];reject(new Error('Failed to load '+url))};document.head.appendChild(script)});return loadedScripts[url]}})();window.createVisualization=function(element,data,callback){if(window.VisualizationTools[data.tool])
window.VisualizationTools[data.tool](element,data,callback);else{window.VisualizationTools.html(element,{data:{html:'Error: No known visualization tool, "'+data.tool+'."'}},callback)}};window.VisualizationTools={html:function(element,json,callback){var div=document.createElement('div');element.appendChild(div);div.innerHTML=json.data.html;if(json.width)$(div).width(json.width);if(json.height)$(div).height(json.height);callback(element,div)}};window.resizeToShowContents=function(element){var maxima={right:0,bottom:0};$(element).find('*').each(function(idx,elt){var $elt=$(elt);var right=$elt.position().left+$elt.outerWidth();var bottom=$elt.position().top+$elt.outerHeight();maxima={right:Math.max(right,maxima.right),bottom:Math.max(bottom,maxima.bottom)}});var $element=$(element);$element.width(maxima.right-$element.position().left);$element.height(maxima.bottom-$element.position().top)}